$ErrorActionPreference='Stop';$taskRuntime='E:/R4D/perspective/p5-runtime/asset-artist/transfer-water-dark/dark';$env:TEMP=Join-Path $taskRuntime 'temp';$env:TMP=$env:TEMP
Add-Type -AssemblyName System.Drawing
$taskMeasurements=Get-Content (Join-Path $taskRuntime 'manifests/image-measurements.json') -Raw|ConvertFrom-Json
function Fit-P5Line($Samples){$taskN=$Samples.Count;$taskSX=0.;$taskSY=0.;$taskSXX=0.;$taskSXY=0.;foreach($taskP in $Samples){$taskSX+=$taskP[0];$taskSY+=$taskP[1];$taskSXX+=$taskP[0]*$taskP[0];$taskSXY+=$taskP[0]*$taskP[1]};$taskA=($taskN*$taskSXY-$taskSX*$taskSY)/($taskN*$taskSXX-$taskSX*$taskSX);$taskB=($taskSY-$taskA*$taskSX)/$taskN;$taskSSE=0.;foreach($taskP in $Samples){$taskSSE+=[math]::Pow($taskP[1]-($taskA*$taskP[0]+$taskB),2)};return @{slope=$taskA;intercept=$taskB;rms=[math]::Sqrt($taskSSE/$taskN)}}
$taskRows=@(foreach($taskName in @('pillar-mid-v1','block-mid-v1')){
 $taskM=$taskMeasurements|Where-Object{[IO.Path]::GetFileNameWithoutExtension($_.file) -eq $taskName};$taskBbox=$taskM.image.contactBounds;$taskMinX=$taskBbox[0];$taskMaxX=$taskMinX+$taskBbox[2]-1;$taskMaxY=$taskBbox[1]+$taskBbox[3]-1
 $taskB=[Drawing.Bitmap]::new($taskM.file)
 try{$taskPeakXs=@(for($taskX=$taskMinX;$taskX -le $taskMaxX;$taskX++){if($taskB.GetPixel($taskX,$taskMaxY).A -ge 128){$taskX}});$taskPeakX=(($taskPeakXs|Measure-Object -Minimum).Minimum+($taskPeakXs|Measure-Object -Maximum).Maximum)/2
 $taskSampleSets=@(foreach($taskRange in @(@($taskMinX,$taskPeakX),@($taskPeakX,$taskMaxX))){$taskSamples=@(foreach($taskF in @(.15,.25,.35,.45,.55,.65,.75,.85)){$taskX=[int][math]::Round($taskRange[0]+($taskRange[1]-$taskRange[0])*$taskF);$taskY=-1;for($taskJ=$taskMaxY;$taskJ -ge 0;$taskJ--){if($taskB.GetPixel($taskX,$taskJ).A -ge 128){$taskY=$taskJ;break}};,@($taskX,$taskY)});,$taskSamples})
 $taskLeftFit=Fit-P5Line $taskSampleSets[0];$taskRightFit=Fit-P5Line $taskSampleSets[1];if([math]::Abs($taskLeftFit.slope-$taskRightFit.slope) -lt .01){throw 'Insufficient independent edges for a quad proxy'}
 $taskFrontX=($taskRightFit.intercept-$taskLeftFit.intercept)/($taskLeftFit.slope-$taskRightFit.slope);$taskFrontY=$taskLeftFit.slope*$taskFrontX+$taskLeftFit.intercept
 $taskLeft=@($taskMinX,($taskLeftFit.slope*$taskMinX+$taskLeftFit.intercept));$taskRight=@($taskMaxX,($taskRightFit.slope*$taskMaxX+$taskRightFit.intercept));$taskFront=@($taskFrontX,$taskFrontY);$taskBack=@(($taskLeft[0]+$taskRight[0]-$taskFrontX),($taskLeft[1]+$taskRight[1]-$taskFrontY));$taskYs=@($taskLeft[1],$taskRight[1],$taskFront[1],$taskBack[1]);$taskDepth=($taskYs|Measure-Object -Maximum).Maximum-($taskYs|Measure-Object -Minimum).Minimum
 [ordered]@{name=$taskName;groundAnchorPx=@((($taskLeft[0]+$taskRight[0])/2),(($taskLeft[1]+$taskRight[1])/2));footprintWidthPx=$taskMaxX-$taskMinX;footprintDepthPx=$taskDepth;ratio=$taskDepth/($taskMaxX-$taskMinX);groundQuadProxyTexturePx=@($taskBack,$taskRight,$taskFront,$taskLeft);frontEdgeFits=@($taskLeftFit,$taskRightFit);samples=$taskSampleSets;basis='Measured two visible lower alpha>=128 base edges; inferred rear vertex by local parallelogram. Rear edge hidden, not recovered3D. No bitmap warp or native adjustment.';uncertaintyTexturePx=12;limits=@('Painted bevels/facets perturb the contact contour; inspect normal-scale corner contacts','One uniform scale only; source depth and corner mismatch remain recorded')}
 }finally{$taskB.Dispose()}
})
$taskText=($taskRows|ConvertTo-Json -Depth 12)-replace "`r`n","`n";[IO.File]::WriteAllText((Join-Path $taskRuntime 'manifests/quad-supports.json'),$taskText+"`n",[Text.UTF8Encoding]::new($false))
$taskRows|ForEach-Object{[ordered]@{name=$_.name;anchor=$_.groundAnchorPx;width=$_.footprintWidthPx;depth=$_.footprintDepthPx;ratio=$_.ratio;fits=$_.frontEdgeFits}}|ConvertTo-Json -Depth 5
